const r = await api.get("/customers", {});
const items = r.items || [];
const nov = items.filter(c => c.birth_date && /^\d{4}-11-/.test(c.birth_date) || (c.birth_date && /^11[\/.]/.test(c.birth_date)));
const sample = items.slice(0,3).map(c => c.birth_date);
return { total: items.length, count: r.count, novemberBirthdays: nov.length, sampleFormats: sample, noBirthDate: items.filter(c => !c.birth_date).length };

